 $('runEvidencePath').addEventListener('click',()=>{try{const result=AtlasExecution.shortestPath(d,$('queryFrom').value,$('queryTo').value,{mode:$('queryMode').value,direction:$('queryDirection').value,context:context()});$('queryResults').textContent=result.status+' · '+result.reason+' · '+result.path.join(' → ');}catch(error){$('queryResults').textContent=error.message;}});
 $('runCandidateSearch').addEventListener('click',async()=>{try{const found=await AtlasExecution.candidates(d,$('queryFrom').value,{context:context(),limit:100});$('queryResults').innerHTML='<p>'+found.length+' bounded candidates. No official admission.</p>'+found.map((c,i)=>'<div class="warn"><button data-candidate="'+i+'">'+esc(c.to)+'</button><p>'+esc(c.status+' · '+c.signals.join(' / '))+'</p><p>'+esc(c.rejectionReasons.join(' / '))+'</p></div>').join('');details.querySelectorAll('[data-candidate]').forEach(b=>b.addEventListener('click',()=>candidatePanel(found[Number(b.dataset.candidate)])));}catch(error){$('queryResults').textContent=error.message;}});
