function candidatePanel(candidate){
 panel('<h3>Candidate evidence & counterevidence</h3><div class="detail-badge">'+esc(candidate.status)+'</div><p>'+esc(candidate.from+' → '+candidate.to)+'</p><p>'+esc(candidate.ruleVersion+' · '+candidate.signals.join(' / '))+'</p><p>'+esc(candidate.rationale)+'</p><h4>Source paths</h4><p>'+esc(candidate.sourcePaths.join(' → ')||'No model path supports this question.')+'</p><h4>Alternative explanation</h4><p>'+esc(candidate.alternativeExplanation)+'</p><h4>Falsifier</h4><p>'+esc(candidate.falsifier)+'</p><h4>Counterevidence / rejection reasons</h4><ul>'+candidate.counterevidence.map(c=>'<li>'+esc(c)+'</li>').join('')+'</ul><label for="researchQuestion">Local research question</label><input id="researchQuestion" maxlength="1000" value="Does the source evidence support this relation?"><label for="researchDecision">Local review decision</label><select id="researchDecision"><option>CONTESTED</option><option>RETRACTED</option>'+(candidate.status==='DISCOVERY_CANDIDATE'?'<option>APPROVED_FOR_RESEARCH</option>':'')+'</select><label for="researchReason">Reason / counterevidence</label><textarea id="researchReason" maxlength="1000"></textarea><button id="saveResearchReview">Append local review</button><p id="researchMessage" role="status"></p>');
 $('contextActions').replaceChildren(button('Back to discovery',discoveryPanel));
 $('saveResearchReview').addEventListener('click',async()=>{try{d=await m.recordResearchReview(d,{candidate,question:$('researchQuestion').value,decision:$('researchDecision').value,reason:$('researchReason').value});$('researchMessage').textContent='Local question and review appended. Export snapshot to retain. No government approval or KNOWN_LINK created.';}catch(error){$('researchMessage').textContent=error.message;}});
}
