function domainEntity(id){
 const e=m.domainIndex(d).get(id);if(!e)return;
 const links=m.queryRelationships(d,id,{direction:'both'}),history=d.domain.revisions.filter(r=>r.logicalId===id);
 panel('<h3>'+esc(e.label)+'</h3><p>'+esc(e.kind+' · '+e.id)+'</p><div class="detail-badge">'+esc(e.classification+' / '+e.state)+'</div><p>Admission '+esc(e.admission)+' · '+esc(e.revisionId)+'</p><h4>Record and calculation inputs</h4><pre class="record-json">'+esc(JSON.stringify(e.data,null,2))+'</pre><h4>Where / when / boundary</h4><pre class="record-json">'+esc(JSON.stringify(e.scope,null,2))+'</pre>'+(e.provenance?'<h4>Source anchor</h4><p>'+esc(e.provenance.locator)+'</p>'+sourceLink(e.provenance.url):'<p>Source: SYNTHETIC_SCENARIO. Not Council work or expenditure.</p>')+'<h4>Upstream / downstream</h4>'+links.map(a=>'<p>'+esc(a.predicate)+' <button data-domain-link="'+esc(a.from===id?a.to:a.from)+'">'+esc(a.from===id?a.to:a.from)+'</button></p>').join('')+'<h4>Revision history</h4>'+history.map(r=>'<details><summary>'+esc(r.id)+'</summary><pre class="record-json">'+esc(JSON.stringify(r.record,null,2))+'</pre></details>').join('')+'<h4>Evidence gaps</h4><ul>'+e.gaps.map(g=>'<li>'+esc(g)+'</li>').join('')+'</ul><label for="domainReason">Local review reason</label><input id="domainReason" maxlength="1000"><button id="contestDomain">Append local challenge</button><p id="domainMessage" role="status"></p><p>Export snapshot to retain this in-memory review. Official approval is unavailable.</p>');
 $('contextActions').replaceChildren(button('Trace back to strategy station',()=>inspectNode(e.stationId)),button('Back to dossier',()=>domainDossier(e.stationId)));
 details.querySelectorAll('[data-domain-link]').forEach(b=>b.addEventListener('click',()=>d.domain.entities.some(e=>e.id===b.dataset.domainLink)?domainEntity(b.dataset.domainLink):inspectNode(b.dataset.domainLink)));
 if(e.classification==='SYNTHETIC_SCENARIO'&&Number.isFinite(e.data.value)){
 const editor=document.createElement('div');editor.innerHTML='<label for="scenarioValue">Synthetic scenario value</label><input id="scenarioValue" type="number" step="any" min="0" value="'+e.data.value+'"><button id="reviseScenarioValue">Append synthetic input revision</button>';details.append(editor);
 $('reviseScenarioValue').addEventListener('click',async()=>{try{const raw=$('scenarioValue').value,value=Number(raw);if(!raw||!Number.isFinite(value)||value<0)throw Error('EXPLICIT_NONNEGATIVE_VALUE_REQUIRED');d=await m.commitDomainRevision(d,{id,expectedRevisionId:e.revisionId,patch:{data:{...e.data,value}},reason:$('domainReason').value.trim()});domainEntity(id);$('domainMessage').textContent='Synthetic value revision appended. Prior receipts retain history; changed-input calculations are invalidated.';}catch(error){$('domainMessage').textContent=error.message;}});
 }
 if(e.kind==='AuditReceipt'){const validity=document.createElement('p');details.append(validity);AtlasExecution.verifyDerivation(d,e.data.receipt).then(result=>validity.textContent='Calculation inputs: '+result.status);}
 $('contestDomain').addEventListener('click',async()=>{try{d=await m.commitDomainRevision(d,{id,expectedRevisionId:e.revisionId,patch:{state:'CONTESTED',localNote:$('domainReason').value},reason:$('domainReason').value});domainEntity(id);$('domainMessage').textContent='Local challenge appended. Prior revisions retained; no source approval changed.';}catch(error){$('domainMessage').textContent=error.message;}});
}
function inspectLink(edge){
 state.selected=null;state.followId=null;const edgeKey=edge.id||edge.from+'->'+edge.to;
 const a=d.assertions.find(a=>a.id===edge.id);
 const from=state.view==='content'?contentById.get(edge.from).title:byId.get(edge.from).label,to=state.view==='content'?contentById.get(edge.to).title:byId.get(edge.to).label;
 panel('<h3>'+esc(from)+' → '+esc(to)+'</h3>'+(a?'<div class="detail-badge">'+esc(a.status)+'</div><p class="detail-text">Predicate: '+esc(a.predicate)+' / Review: '+esc(a.reviewStatus)+'</p><p class="detail-text">Revision '+esc(a.revisionId)+' · Region '+esc(a.region)+' · '+esc(a.validFrom)+' to '+esc(a.validTo)+'</p><p class="detail-text">Supporting references: '+a.evidenceRefs.length+' · Counter-references: '+a.counterevidenceRefs.length+'</p><div class="warn">Synthetic or research relationship. No official source-to-clause mapping has been admitted.</div>':'<div class="detail-badge">CONTAINS</div><p class="detail-text">This is internal content containment. It does not establish statutory effect or a cross-document policy relationship.</p>'));
 lastEdgeFocus=edgeKey;$('contextActions').replaceChildren(button('Trace origin',()=>state.view==='content'?inspectContent(edge.from):inspectNode(edge.from)),button('Follow destination',()=>state.view==='content'?inspectContent(edge.to):inspectNode(edge.to)),button('Challenge this connection',()=>{$('discoveryBtn').click();}));
}
