async function auditPanel({eventOffset=0,revisionOffset=0}={}){
 const dataset=d,current=panel('<h3>Audit & version history</h3><p>Recomputing all retained integrity layers…</p>');
 try{const audit=await m.auditSnapshot(dataset);if(current!==request)return;
 const events=[...dataset.events.map(e=>({...e,layer:'BASE_FIXTURE'})),...dataset.domain.events.map(e=>({...e,layer:'DOMAIN_RESEARCH'})),...(dataset.domain.sourceCatalogue?.events||[]).map(e=>({...e,layer:'SOURCE_INTAKE'}))].reverse(),revisions=dataset.domain.revisions.slice().reverse();
 details.innerHTML='<h3>Audit & version history</h3><p>'+esc(audit.datasetDigest)+'</p><p>Structure issues: '+audit.issues.length+' · Event chain: '+(audit.historyValid?'PASS':'FAIL')+'</p><p>SELF_ATTESTED · RECEIPT_NOT_PRESENT · EXTERNAL_WITNESS_UNKNOWN</p><h4>Events '+eventOffset+'–'+Math.min(eventOffset+30,events.length)+' / '+events.length+'</h4>'+events.slice(eventOffset,eventOffset+30).map(e=>'<div class="warn"><strong>'+esc(e.layer+' · '+(e.type||e.operation)+' · '+(e.objectId||e.sourceId))+'</strong><p>'+esc(e.observedAt||e.evidence?.at)+'</p><p>'+esc(e.reason||e.evidence?.reason)+'</p><p>'+esc(e.digest)+'</p></div>').join('')+'<div id="eventPages"></div><h4>Revision field differences '+revisionOffset+'–'+Math.min(revisionOffset+15,revisions.length)+' / '+revisions.length+'</h4>'+revisions.slice(revisionOffset,revisionOffset+15).map(rev=>{const parent=dataset.domain.revisions.find(p=>p.id===rev.parentRevision);return '<details><summary>'+esc(rev.logicalId+' · '+rev.id)+'</summary>'+AtlasExecution.diffRecords(parent?.record||{},rev.record).map(diff=>'<p>'+esc(diff.field)+'</p><pre class="record-json">'+esc(JSON.stringify(diff.before))+' → '+esc(JSON.stringify(diff.after))+'</pre>').join('')+'</details>';}).join('')+'<div id="revisionPages"></div><p>Original content, semantic assertions, source intake, calculations and local research have separate histories. Integrity is not source rights, truth, legal applicability or official approval. Full history is included in explicit exports.</p>';
 if(eventOffset)$('eventPages').append(button('Newer events',()=>auditPanel({eventOffset:Math.max(0,eventOffset-30),revisionOffset})));if(eventOffset+30<events.length)$('eventPages').append(button('Older events',()=>auditPanel({eventOffset:eventOffset+30,revisionOffset})));
 if(revisionOffset)$('revisionPages').append(button('Newer revisions',()=>auditPanel({eventOffset,revisionOffset:Math.max(0,revisionOffset-15)})));if(revisionOffset+15<revisions.length)$('revisionPages').append(button('Older revisions',()=>auditPanel({eventOffset,revisionOffset:revisionOffset+15})));
 }catch{if(current===request)details.textContent='Audit failed. Do not rely on this dataset.';}
}
