 $('saveWorkspace').addEventListener('click',async()=>{if(workspaceBusy)return;workspaceBusy=true;try{storageCheckpoint=await w.saveLocal(workspace,d,storageCheckpoint);message('Saved locally. Checkpoint '+storageCheckpoint);}catch(e){message(e.message);}finally{workspaceBusy=false;}});
 $('loadWorkspace').addEventListener('click',async()=>{if(workspaceBusy)return;workspaceBusy=true;try{const saved=await w.loadLocal(workspace.baseDigest);if(!saved){message('No saved workspace for this dataset.');return;}const loaded=await w.importWorkspace(JSON.stringify(saved.workspace),d,saved.checkpoint);if(workspace.revisions.length&&!w.extendsHistory(workspace,loaded))throw Error('LOAD_CONFLICT: export your unsaved branch before loading another history');workspace=loaded;storageCheckpoint=saved.checkpoint;await workspacePanel();message('Loaded and verified '+workspace.revisions.length+' local revisions.');}catch(e){message(e.message);}finally{workspaceBusy=false;}});
 $('workspaceImport').addEventListener('change',async e=>{if(workspaceBusy)return;workspaceBusy=true;try{const file=e.target.files[0];if(!file)return;if(file.size>2*1024*1024)throw Error('IMPORT_TOO_LARGE');const loaded=await w.importWorkspace(await file.text(),d);if(!w.extendsHistory(workspace,loaded)){await mergePanel(loaded);return;}workspace=loaded;await workspacePanel();message('Imported and verified; not saved locally until you click Save locally.');}catch(error){message('Import rejected: '+error.message);}finally{workspaceBusy=false;}});
